pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        vm.deal(address(this), 2 ether);
        c = new C{value: 1 ether}();
    }
    function testFuzz_property(bytes32 hash) public {
        vm.assume(address(this).balance >= 1 ether);
        vm.prank(address(this));
        c.lockInGuess{value: 1 ether}(hash);
        (bool ok, bytes memory data) = address(c).call(abi.encodeWithSignature("guesses(address)", address(this)));
