pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C{value: 1 ether}();
    }
    function testFuzz_property(bytes32 guessHash) public {
        // 1. Admissible domain: guessHash can be any bytes32
        // 2. Set up: fund a user, they lock in a guess
        address user = address(0x1234);
        vm.deal(user, 10 ether);
        vm.prank(user);
        c.lockInGuess{value: 1 ether}(guessHash);

        // Warp to a block where the stored blockhash is available (> stored block, <= 256 blocks later)
        // The stored block is block.number+1 for P, block.number+2 for M. We warp to block.number+100.
        vm.roll(block.number + 100);

        // Try to settle
        vm.prank(user);
        try c.settle() {
            // If it doesn't revert, check that balance increased correctly if guess matches
            // We need to assert a general rule: if the guess matches the blockhash of the block
            // that settle() uses (which is the stored block), then the user must receive 2 ether.
            // Since P stores block.number+1, settle uses that blockhash. M stores block.number+2,
            // so settle uses a different blockhash — if user's guess matches P's blockhash,
            // they get paid; in M, the blockhash is different, so either guess doesn't match (no pay),
            // or it accidentally matches (pay). But the rule is: if guess == blockhash(stored block before settle),
            // then after settle user balance increases by 2 ether. P ensures stored block = lock block + 1,
            // so we can compute the expected blockhash externally. M violates because stored block is lock block + 2,
            // so the blockhash returned by settle() is different and the equality doesn't hold.
            //
            // We read the stored guess and the blockhash of the block that settle should use (lock block + 1 for P).
            // The rule: If guessHash == blockhash(lockBlock + 1), then user must have been paid 2 ether.
            // lockBlock is the block.number at the time lockInGuess was called (we can record it).
            // We do this by using vm.roll to control block.number.
            uint256 lockBlock = block.number - 100; // since we rolled +100, lockBlock is current -100
            bytes32 expectedAnswer = blockhash(lockBlock + 1); // P stores lockBlock+1
            bool guessCorrect = (guessHash == expectedAnswer && expectedAnswer != 0);

            uint256 balanceBefore = user.balance;
            // already settled above, balanceAfter is current balance
            uint256 balanceAfter = user.balance;

            if (guessCorrect) {
                assertEq(balanceAfter - balanceBefore, 2 ether, "Correct guess should yield 2 ether");
            }
        } catch {
            // If settle reverts, it means the guess was not eligible (maybe stored block not yet passed, but we warped).
            // This is fine as long as it doesn't revert for wrong reasons. No universal assertion needed on revert.
        }
    }
}

