        c = new C{value: 1 ether}();
    }

    function testFuzz_property(bytes32 hash, uint256 actorSeed) public {
        // Use actorSeed to generate a deterministic, non-zero address to avoid the deployer (address(this))
        address actor = address(uint160(uint256(keccak256(abi.encode(actorSeed)))));
        // Avoid zero address and the deployer
        vm.assume(actor != address(0) && actor != address(this));

        // Fund the actor with enough ether to call lockInGuess multiple times
