contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 hash, uint8 fuzzBlockOffset) public {
        // fuzzBlockOffset ensures we test settle in a future block, not restricted to a single value
        vm.assume(fuzzBlockOffset > 0);
        address actor = address(0x1234);
        vm.deal(actor, 1 ether);

        // 1. actor locks in a guess
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(hash);

        // 2. Advance to a future block (fuzzed offset)
        vm.roll(block.number + fuzzBlockOffset);

        // 3. attempt to settle
        bool ok;
        vm.prank(actor);
        try c.settle() { ok = true; } catch { ok = false; }

        // The correct contract: stored block was block.number+1 at lock time, so after advancing,
        // block.number > storedBlock is true -> settle can proceed (it might revert if hash doesn't match, but the call doesn't revert due to the require on block).
        // The buggy contract: stored block is 0, so block.number > 0 is always true, and settle executes immediately.
        // The invariant: if settle is called in the same transaction as lockInGuess (i.e., without advancing blocks), it should revert because block.number <= storedBlock.
        // We frame the property differently: after advancing blocks, the correct contract's settle call should succeed (ok == true) when block.number > storedBlock,
        // but the buggy one also succeeds. That's not a difference.
        // Revised invariant: calling settle immediately after lockInGuess (no block advance) MUST revert.
        // Let's use that.
    }
}

