pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bytes32 guessHash, uint256 blockOffset) public {
        // domain: blockOffset must be > 0 so settle block is strictly after lock-in block
        vm.assume(blockOffset > 0);

        // fund an actor and lock in a guess
        address actor = address(0x1234);
        vm.deal(actor, 10 ether);
        vm.startPrank(actor);
        c.lockInGuess{value: 1 ether}(guessHash);

        // advance blocks so the guess block is fixed and then becomes eligible for settle
        uint256 settleBlock = block.number + blockOffset;
        vm.roll(block.number + blockOffset + 1);

        // force blockhash at settle block to equal the guess hash to make answer non-zero and match
        vm.roll(settleBlock + 1);
        // mine enough blocks to ensure blockhash is available (up to 256 blocks back)
        // we already rolled to settleBlock+1; now store the blockhash to use in cheat
        bytes32 forcedAnswer = blockhash(settleBlock);
        // if forcedAnswer is 0 (blockhash not available), we can't force; skip this run
        vm.assume(forcedAnswer != 0 && forcedAnswer == guessHash);

        // record pre-settle contract balance
        uint256 balanceBefore = address(c).balance;

        // settle; the answer matches the guess, so payout will happen
        c.settle();
        vm.stopPrank();

        // after a successful settle where answer matched, the contract balance should have decreased by exactly 2 ether
        // (payout is 2 ether, no other funds move in settle)
        assertTrue(address(c).balance == balanceBefore - 2 ether);
    }
}

