pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockNumber, bytes32 guessHash) public {
        // Ensure blockNumber is in the admissible range (past deploy, within recent blocks for blockhash)
        vm.assume(blockNumber > block.number);
        vm.assume(blockNumber < block.number + 256);
        // Set up a caller with enough ether
        address caller = address(0x1234);
        vm.deal(caller, 10 ether);
        // Lock in guess
        vm.prank(caller);
        c.lockInGuess{value: 1 ether}(guessHash);
        // Advance to block where blockhash is available
        vm.roll(blockNumber);
        // Settle
        vm.prank(caller);
        c.settle();
        // After settling, if guess matches the blockhash, caller should not receive 2 ETH (balance should be 1 ETH less)
        // The reference: payout only when guess == answer, so balance stays with contract if matched.
        // The bug: payout when guess != answer, so balance stays with contract if NOT matched.
        // The general rule: if guess == answer, contract balance must be at least 2 ether (no payout).
        bytes32 answer = blockhash(blockNumber - 1);
        if (guessHash == answer && answer != 0) {
            assertTrue(address(c).balance >= 2 ether);
        } else {
            assertTrue(true);
        }
    }
}

